const G=2,S=1.05;
const D={moveUp:[1,0,'up'],moveDown:[-1,0,'down'],moveLeft:[0,-1,'left'],moveRight:[0,1,'right']};
export function initialState(){return{r:0,c:0,moves:0,hint:false,won:false,msg:'Reach the green goal square.'};}
function dist(s){return Math.abs(G-s.r)+Math.abs(G-s.c);}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;
if(state.won)return{...state,msg:'You already won. Press Reset to play again.'};
if(a==='showHint')return{...state,hint:true,msg:state.c<G?'Hint: move Right.':'Hint: move Up.'};
const d=D[a];if(!d)return state;
const r=state.r+d[0],c=state.c+d[1];
if(r<0||r>G||c<0||c>G)return{...state,hint:false,msg:'Can\'t move '+d[2]+': that would leave the board.'};
const n={...state,r,c,moves:state.moves+1,hint:false};
if(r===G&&c===G){n.won=true;n.msg='Goal reached in '+n.moves+' moves! The shortest route is 4 moves'+(n.moves===4?' - perfect!':'.');}
else n.msg='Moved '+d[2]+'. '+dist(n)+' steps to go.';
return n;}
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*S,z=-(s.r-1)*S,onG=s.r===G&&s.c===G;
const y=onG?0.43:0.35;
const q=s.c<G?[0,0,-0.7071068,0.7071068]:[-0.7071068,0,0,0.7071068];
return{nodes:{tokenN:{position:[x,y,z]},hintN:{position:[x,y,z],quaternion:q,visible:s.hint&&!s.won}},
readouts:{moves:s.moves,steps:dist(s)},
goal:{status:s.won?'won':'playing',message:s.msg}};}
